import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.CbQjVMS6.js";const m=JSON.parse('{"title":"","titleTemplate":false,"description":"","frontmatter":{"layout":"home","titleTemplate":false,"hero":{"name":"PieTeams","text":"Open-source data and knowledge engineering","tagline":"We build practical, auditable and self-hostable software for teams that treat data as an asset — not a by-product.","actions":[{"theme":"brand","text":"Explore projects","link":"/projects"},{"theme":"alt","text":"Read our insights","link":"/insights/"},{"theme":"alt","text":"GitHub","link":"https://github.com/pieteams"}]},"features":[{"title":"PieKBS","details":"An agent-native knowledge base. Distills raw documents into a reviewable Markdown wiki and serves it to AI agents through MCP.","link":"https://pieteams.github.io/piekbs/"},{"title":"PieMDM","details":"A full-stack Master Data Management platform for enterprises, with modeling, governance, approval workflows and open APIs.","link":"https://pieteams.github.io/piemdm/"},{"title":"PiePLM","details":"An open, documentation-first blueprint for affordable Product Lifecycle Management in small and mid-sized manufacturers.","link":"https://pieteams.github.io/pieplm/"},{"title":"Open by default","details":"Our projects are MIT licensed. Schemas, data models and decisions live in plain files that you can diff, review and own."},{"title":"Self-hostable","details":"No lock-in and no mandatory cloud account. Run the software on your own laptop, server or private network."},{"title":"Agent-ready","details":"Knowledge and business data are exposed through documented APIs and the Model Context Protocol for AI agents."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794023466000}'),i={name:"index.md"};function o(r,e,l,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h2 id="what-we-work-on" tabindex="-1">What we work on <a class="header-anchor" href="#what-we-work-on" aria-label="Permalink to &quot;What we work on&quot;">​</a></h2><p>PieTeams is an independent open-source team. We focus on one problem: <strong>how organisations keep knowledge and master data usable over time</strong>.</p><p>Most software stores data. Far less software makes that data understandable — to new employees, to downstream systems and to AI agents. Our projects approach the same problem from three angles:</p><table tabindex="0"><thead><tr><th>Project</th><th>Question it answers</th><th>Primary users</th></tr></thead><tbody><tr><td><strong>PieKBS</strong></td><td>How do we turn scattered documents into knowledge an agent can search and cite?</td><td>AI engineers, researchers, technical teams</td></tr><tr><td><strong>PieMDM</strong></td><td>How do we keep customers, suppliers, products and other master data consistent?</td><td>Data stewards, enterprise IT, operations</td></tr><tr><td><strong>PiePLM</strong></td><td>How can smaller manufacturers manage product information without a heavyweight PLM suite?</td><td>Manufacturing SMEs, product teams</td></tr></tbody></table><h2 id="how-we-build" tabindex="-1">How we build <a class="header-anchor" href="#how-we-build" aria-label="Permalink to &quot;How we build&quot;">​</a></h2><ul><li><strong>Explicit over implicit.</strong> A Markdown page you can review beats a vector you cannot explain.</li><li><strong>Small over sprawling.</strong> One binary or one focused platform beats a suite of half-used modules.</li><li><strong>Standards over lock-in.</strong> SQL, HTTP, OpenAPI and MCP are interfaces we can all inspect.</li><li><strong>Documentation as a deliverable.</strong> If a feature cannot be explained, it is not finished.</li></ul><h2 id="latest-insights" tabindex="-1">Latest insights <a class="header-anchor" href="#latest-insights" aria-label="Permalink to &quot;Latest insights&quot;">​</a></h2><ul><li><a href="/insights/agent-native-knowledge">Why agents need a search engine, not an answer machine</a></li><li><a href="/insights/rag-vs-llm-wiki">RAG vs. LLM wiki: two ways to give agents knowledge</a></li><li><a href="/insights/master-data-management">When a growing company actually needs master data management</a></li><li><a href="/insights/plm-for-smes">Product lifecycle management for small manufacturers</a></li></ul><h2 id="stay-in-touch" tabindex="-1">Stay in touch <a class="header-anchor" href="#stay-in-touch" aria-label="Permalink to &quot;Stay in touch&quot;">​</a></h2><p>Questions, bug reports and feature requests are welcome in the GitHub issue tracker of the relevant project. For anything about this website, use the <a href="https://github.com/pieteams/pieteams.github.io/issues" target="_blank" rel="noreferrer">PieTeams website repository</a>. See the <a href="/contact">contact page</a> for details.</p>',10)])])}const p=t(i,[["render",o]]);export{m as __pageData,p as default};
